function secondHighest(s) {
  let first = -1;
  let second = -1;

  for (const ch of s) {
    if (ch < '0' || ch > '9') {
      continue;
    }
    const digit = Number(ch);
    if (digit > first) {
      second = first;
      first = digit;
    } else if (digit < first && digit > second) {
      second = digit;
    }
  }
  return second;
}

brute:
function secondHighest(s) {
  const digits = [...new Set(s.split('').filter(c => /[0-9]/.test(c)).map(Number))];
  digits.sort((a, b) => b - a);
  return digits.length >= 2 ? digits[1] : -1;
}

