function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const n = size === 'large' ? 500 : 1 + Math.floor(rand() * 12);
  // Use a random handful of digit values and a random share of digits so every outcome appears.
  const pool = '0123456789'.split('').filter(() => rand() < 0.4);
  const share = rand() < 0.15 ? 0 : rand();
  let s = '';
  for (let i = 0; i < n; i++) {
    if (pool.length > 0 && rand() < share) s += pool[Math.floor(rand() * pool.length)];
    else s += letters[Math.floor(rand() * 26)];
  }
  return [s];
}
